window.RP_SESSION={"id":"S-2c7a182dcae6","messages":[{"id":"RP-II-0122694","time":"2026-07-23T20:12:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 배고프다. 괴로워. 마지막으로 무언가를 입에 넣은게 얼마나 되었던가?","characters":[]},{"id":"RP-II-0122695","time":"2026-07-23T20:14:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 시야가 뿌옇게 흐렸다. 아이는 굶주린 물고기가 공기를 먹듯, 작은 손에 흙을 가득 쥐었다.","characters":[]},{"id":"RP-II-0122696","time":"2026-07-23T20:15:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 습기찬 흙에서 지렁이가 꿈틀꿈틀 기어나왔다.","characters":[]},{"id":"RP-II-0122697","time":"2026-07-23T20:16:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 길을 잃은지 얼마나 된거지? 땅이 녹은 이후론 계속 숲 속에서 헤메기만 했다.","characters":[]},{"id":"RP-II-0122698","time":"2026-07-23T20:17:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그러나 아이는 아직 셈을 할 줄 못했기에, 자신이 지붕 없이 겨울을 났었다는 걸 다행으로 여기는 것 외엔 할 수 없었다. 안개가 짙어져갔다.","characters":[]},{"id":"RP-II-0122699","time":"2026-07-23T20:19:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":"안개가 짙어져갔다. 아이는 걸었다.","characters":[]},{"id":"RP-II-0122700","time":"2026-07-23T20:19:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":"안개가 짙어져갔다. 아이는 넘어졌다.","characters":[]},{"id":"RP-II-0122701","time":"2026-07-23T20:21:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 넘어져서 아팠지만 울음이 나오지 않았다. 흐를 눈물이 아깝다고 생각하였다. 엄마가 보고 싶었다. 미운 엄마, 불쌍한 엄마. 내 목소리를 앗아가고 움직이지 않게 된 나의 엄마. 그를 배척되게 된 것을 내가 가지고 태어났기에 나를 배척한 사람.","characters":[]},{"id":"RP-II-0122702","time":"2026-07-23T20:24:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아이는 기다시피하며 걸었다. 말도 못 하니 아기 때로 돌아간 기분이 들었다. 왜 걷는 지는 알 수 없었지만 그저 살고 싶었다.","characters":[]},{"id":"RP-II-0122703","time":"2026-07-23T20:24:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":"살아남기.","characters":[]},{"id":"RP-II-0122704","time":"2026-07-23T20:25:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그 욕망은 자연이 모든 것에 공통으로 준 유일한 것.","characters":[]},{"id":"RP-II-0122705","time":"2026-07-23T20:25:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그것만이 아이에게 남아있게 되었을 때, 목소리가 들렸다.","characters":[]},{"id":"RP-II-0122706","time":"2026-07-23T20:26:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":"두 발이 있다. 사람이었다.","characters":[]},{"id":"RP-II-0122707","time":"2026-07-23T20:27:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '인간 아이? 여긴 길을 잃는다고 올 수 있는 곳이 아닌데?'","characters":[]},{"id":"RP-II-0122708","time":"2026-07-23T20:28:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 모르는 언어였지만, 어쩐지 알아들을 수 있었다. 아이는 물을 달라고 하고 싶었지만, 마른 입술만 뻥긋할 수 있을 뿐이었다.","characters":[]},{"id":"RP-II-0122709","time":"2026-07-23T20:37:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '사람을 본 건 수십년 만인데, 그게 아사 직전의 어린애라니-'\n 그는 계속해서 알아들을 수 없는 이야기를 하더니, 아이를 들어올렸다.","characters":[]},{"id":"RP-II-0122710","time":"2026-07-23T20:37:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '좋아, 내가 너를 돌봐주마 얘야. 아주 소중하고 특별하게 대해줄 테니 걱정마렴.'","characters":[]},{"id":"RP-II-0122711","time":"2026-07-23T20:38:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 10년 전 초봄의 일이었다.","characters":[]},{"id":"RP-II-0122712","time":"2026-07-23T20:38:00+09:00","room":"RP II","name":"서술 / 이름 없는 아이·보호자","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0122713","time":"2026-07-23T20:38:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
